import type { MetadataRoute } from 'next';

// Web app manifest: gives Android / desktop installs the Heart Line icon instead of a
// screenshot or the browser default. Icons are generated by scripts/build-app-icons.mjs.
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: 'CC Saint-Martin Blanmont',
    short_name: 'Blanmont',
    description: 'Club cycliste sur route et VTT à Blanmont (Chastre, Brabant wallon).',
    lang: 'fr-BE',
    start_url: '/',
    display: 'browser',
    background_color: '#fbfbf8',
    theme_color: '#fbfbf8',
    icons: [
      { src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
      { src: '/icons/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
      { src: '/icons/icon-maskable-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
    ],
  };
}
